import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, SRGBColorSpace } from 'three/webgpu';
import { texture, uv, float, vec4, hash, floor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const tex = ctx.textureLoader(config.assets.imageUrl);
  try { tex.colorSpace = SRGBColorSpace; } catch (e) {}

  const aspect = 512 / 320;
  const planeWidth = 2.0;
  const planeHeight = planeWidth / aspect;
  const geometry = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.opacity = 0;

  const baseColor = texture(tex, uv());

  const grainScale = float(900.0);
  const grainCell = uv().mul(grainScale).floor();
  const grainVal = hash(grainCell);
  const grainAmt = grainVal.mul(float(0.05)).sub(float(0.025));

  material.colorNode = baseColor.add(vec4(grainAmt, grainAmt, grainAmt, float(0.0)));

  const mesh = new Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  const startY = -0.3 + 0.2;
  mesh.position.y = startY;

  const tl = gsap.timeline();
  tl.to(mesh.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(mesh.position, { y: -0.3, duration: 0.5, ease: 'power2.out' }, 0);

  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    tl.kill();
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
